const course = $('Course details').first().json;
const people = $input.all();

const trainees = people.map(({ json: person }, i) => ({
  name: person.name,
  email: person.email,
  company: person.company?.name ?? '',
  course_title: course.course_title,
  course_hours: course.course_hours,
  completion_date: course.completion_date,
  instructor: course.instructor,
  certificate_id: `${course.certificate_prefix}-${String(person.id).padStart(4, '0')}`,
  page_break: i < people.length - 1,
}));

return [{ json: { trainees } }];

const { trainees } = $('Prepare certificate data').first().json;
const files = $input.first().binary;

// the split files are numbered in page order sort numerically so 10 comes after 9
const pageOf = (key) => Number(files[key].fileName.match(/(\d+)\.pdf$/i)?.[1] ?? 0);
const keys = Object.keys(files).sort((a, b) => pageOf(a) - pageOf(b));

return keys.map((key, i) => ({
  json: {
    name: trainees[i].name,
    email: trainees[i].email,
    certificate_id: trainees[i].certificate_id,
    file_name: `Certificate ${trainees[i].certificate_id} ${trainees[i].name}`,
  },
  binary: { data: files[key] },
}));
